// Función que convierte texto de formato Markdown a HTML
std::string markdownToHtml(const std::string& markdown) {
    // Reglas de conversión de Markdown a HTML
    static const std::regex markdown_regex{
        R"(
        #(\S+)               # Heading 1 (\1)
        ##(\S+)              # Heading 2 (\2)
        ###(\S+)             # Heading 3 (\3)
        ####(\S+)            # Heading 4 (\4)
        #####(\S+)           # Heading 5 (\5)
        ######(\S+)          # Heading 6 (\6)

        \*([^\* ]+)\*        # Bold (\1)
        \*{2}([^\* ]+)\*     # Strong (\2)

        \*([^\* ]+ )\*       # Emphasis (\1)
        \*_{([^\* ]+ )}\*    # Underline (\1)

        \~{2}([^\~ ]+)\~     # Strike (\1)

        \_([^\_ ]+)\_        # Code (\1)

        \!\[(.*?)\]\((.*?)\)# Image ([2]: [1])

        \[(.*?)\]\((.*?)\)\s*# Link ([2]: [1])

        (?:\n\r?|\r\n?)+    # Salto de línea
        )",
        std::regex::optimize
    };

    std::string html;
    std::smatch match;

    while (std::regex_search(markdown, match, markdown_regex)) {
        std::string text = match[0].str();
        std::string replacement;

        switch (match.size()) {
            case 2:
                replacement = "<h1>" + match[1] + "</h1>";
                break;
            case 3:
                replacement = "<h2>" + match[2] + "</h2>";
                break;
            case 4:
                replacement = "<h3>" + match[3] + "</h3>";
                break;
            case 5:
                replacement = "<h4>" + match[4] + "</h4>";
