                replacement = "<strong>" + match[1] + "</strong>";
                break;
            case 9:
                replacement = "<em>" + match[1] + "</em>";
                break;
            case 10:
                replacement = "<u>" + match[1] + "</u>";
                break;
            case 11:
                replacement = "<del>" + match[1] + "</del>";
                break;
            case 12:
                replacement = "<code>" + match[1] + "</code>";
                break;
            case 13:
                replacement = "<img src=\"" + match[2] + "\" alt=\"" + match[1] + "\">";
                break;
            case 14:
                replacement = "<a href=\"" + match[2] + "\">" + match[1] + "</a>";
