4. Finalmente, agrega el enlace para abrir el modal y los scripts para la funcionalidad de envío de mensajes. Aquí hay un ejemplo:

```html
<!-- Button to open modal -->
<button type="button" class="btn btn-primary" data-toggle="modal" data-target="#chat-modal">
  Iniciar conversación
</button>

<!-- jQuery and Bootstrap JS -->
<script src="https://code.jquery.com/jquery-3.5.1.slim.min.js"></script>
<script src="https://cdn.jsdelivr.net/npm/popper.js@1.16.1/dist/umd/popper.min.js"></script>
<script src="https://stackpath.bootstrapcdn.com/bootstrap/4.5.2/js/bootstrap.min.js"></script>

<!-- Custom script to handle message sending -->
<script>
  // Get the form
  var form = document.querySelector('.chat-form form');

  // Get the message input field
  var messageInput = document.getElementById('chat-message-input');

  // Get the chat log
  var chatLog = document.querySelector('.chat-log');

  // Submit message when form is submitted
  form.addEventListener('submit', function(event) {
    // Prevent default form submission
    event.preventDefault();

    // Get the message text
    var messageText = messageInput.value;

    // Create a new chat message element
    var newChatMessage = document.createElement('li');
    newChatMessage.classList.add('chat-message');
    newChatMessage.setAttribute('data-chat', 'human');

    // Add the message text
    var messageParagraph = document.createElement('p');
    messageParagraph.textContent = messageText;
    newChatMessage.appendChild(messageParagraph);

    // Append the new chat message to the chat log
    chatLog.appendChild(newChatMessage);

    // Clear the message input field
    messageInput.value = '';

    // Send the message to the bot (simulated)
    var botMessageText = `¡Gracias por tu mensaje! ${messageText} - Respuesta del asistente de IA`;
    var newBotChatMessage = document.createElement('li');
    newBotChatMessage.classList.add('chat-message');
    newBotChatMessage.setAttribute('data-chat', 'bot');

    var botMessageParagraph = document.createElement('p');
    botMessageParagraph.classList.add('text-white');
    botMessageParagraph.textContent = botMessageText;
    newBotChatMessage.appendChild(botMessageParagraph);

    chatLog.appendChild(newBotChatMessage);
  });
</script>
```

