#include <string>

using namespace std;

int main() {
    string wordToSearch; // palabra a buscar
    string currentLine; // línea actual del archivo

    // Obtener la palabra a buscar desde el usuario
    cout << "Introduzca la palabra a buscar: ";
    getline(cin, wordToSearch);

    // Abrir el archivo para leer
    ifstream inputFile("archivo.txt");

    if (!inputFile) {
        cout << "Error al abrir el archivo." << endl;
        return 1;
    }

    int wordCount = 0; // Contador de apariciones de la palabra

    // Leer línea por línea del archivo
    while (getline(inputFile, currentLine)) {
        // Comprobar si la línea contiene la palabra a buscar
        size_t position = currentLine.find(wordToSearch);
        while (position != string::npos) {
            wordCount++; // Incrementar el conteo si se encuentra la palabra
            position = currentLine.find(wordToSearch, position + 1); // Buscar la siguiente aparición
        }
    }

    // Cerrar el archivo
    inputFile.close();

    cout << "El número de apariciones de \"" << wordToSearch << "\" en el archivo es: " << wordCount << endl;

    return 0;
}
```

En este ejemplo, se solicita al usuario la palabra a buscar, se abre el archivo para lectura, se lee línea por línea, se busca la palabra en cada línea y se incrementa el conteo de apariciones si se encuentra la palabra. Finalmente, se muestra el número de apariciones de la palabra en el archivo.

Recuerda cambiar el nombre del archivo en la línea `ifstream inputFile("archivo.txt");` por el nombre del archivo que deseas leer.

